css:
/* 监控美学 · Surveillance
   闭路电视质感：去饱和灰绿、高对比、扫描线、暗角、时间码与 REC 标记。
   界面元素机械、0 圆角、细描边，红色只留给告警与录制点。纯 CSS。 */

html[data-theme] {
  color-scheme: dark;
  --bg: #0a0d0c;
  --ink: #d5ddD8; --muted: #8d9a93; --dim:#73837c;
  --soft: #b6c1bb; --meta: #8d9a93; --bright: #f2f6f3;
  --line: #29332e; --line2: #1b2420;
  --accent: #ff3b30; --accent2: #9fb3a8; --accentText:#0b0b0c;
  --good: #7fd6a4; --warn: #ffcb5c;
  --glow1: rgba(255, 59, 48, 0.14); --glow2: rgba(159, 179, 168, 0.1);
  --panel: #101513; --panel2: #131a16;
  --dock1: #0e1311; --dock2: #0a0e0c;
  --glass: #0e1311;
  --track: #1f2723; --scroll: #3b4a43; --coverbg: #141a17;
  --menu: #101513; --menu1: #141b17; --menu2: #0b100e; --chev: #7e8f86;
  --edge: #334039; --edge2: #4a2b29;
  --hover: #161d19; --tick: #2a332e;
  --inset: rgba(255, 255, 255, 0.05); --wordactive: #ffffff; --swborder: #3b4a43;
  --shadow-dock: 0 0 0 1px #334039, 0 0 40px -18px rgba(255, 59, 48, 0.28);
  --serif: "Bahnschrift", "DIN Alternate", "PingFang SC", "Microsoft YaHei", sans-serif;
  --sans: "Bahnschrift", "DIN Alternate", "Microsoft YaHei", sans-serif;
  --mono: "Cascadia Code", "SFMono-Regular", Consolas, monospace;
  --bottom: 132px;
  --shell-nav: #0b100e; --shell-nav2: #0b100e;
  --shell-navin: #d5ddd8; --shell-navmuted: #8d9a93; --shell-navline: #29332e;
  --accent-ink:#ff3b30;}

html[data-theme] body {
  background:
    radial-gradient(900px 620px at 50% 44%, rgba(120, 150, 135, 0.08), transparent 66%),
    linear-gradient(180deg, #0a0d0c, #070a09 60%, #050807);
  color: #d5ddd8;
}
/* 扫描线 + 暗角 + 轻微闪烁 */
html[data-theme] body::before {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 2;
  background:
    repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.05) 0 1px, transparent 1px 3px),
    radial-gradient(120% 100% at 50% 50%, transparent 52%, rgba(0, 0, 0, 0.55) 100%);
  animation: cctv-flicker 7s steps(60) infinite;
}
html[data-theme] body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 3; opacity: 0.35;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.95' numOctaves='2'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='0.3'/></svg>");
  mix-blend-mode: overlay;
}
@keyframes cctv-flicker { 0%, 97%, 100% { opacity: 1; } 98% { opacity: 0.86; } 99% { opacity: 0.94; } }
@media (prefers-reduced-motion: reduce) { html[data-theme] body::before { animation: none; } }

/* 侧栏：机柜面板 */
html[data-theme] .sidebar {
  margin: 0; padding: 18px 12px; border-right: 1px solid #29332e; border-radius: 0;
  background: linear-gradient(180deg, #0d1210, #080c0a); box-shadow: inset -12px 0 30px -24px #000;
}
html[data-theme] .brand { padding: 0 6px 16px; border-bottom: 1px solid #29332e; margin-bottom: 12px; }
html[data-theme] .brand .brand-name, html[data-theme] .brand strong {
  font-family: var(--mono); font-size: 11px; letter-spacing: 0.2em; text-transform: uppercase; color: #d5ddd8;
}
html[data-theme] .nav button {
  border: 1px solid transparent; border-radius: 0; padding: 7px 10px;
  font-family: var(--mono); font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase; color: #8d9a93;
}
html[data-theme] .nav button:hover { color: #d5ddd8; border-color: #334039; background: #131a16; }
html[data-theme] .nav button.active {
  color: #ffffff; background: rgba(255, 59, 48, 0.16); border-color: #ff3b30;
  box-shadow: inset 3px 0 0 #ff3b30;
}

/* 顶栏：摄像机状态条 */
html[data-theme] .topbar {
  margin-top: 0; padding: 0 14px; height: 50px; border-bottom: 1px solid #29332e; border-radius: 0;
  background: #0a0e0c; backdrop-filter: none; -webkit-backdrop-filter: none;
}
html[data-theme] .search-global { border: 1px solid #29332e; border-radius: 0; background: #101513; }
html[data-theme] .icon-btn { border: 1px solid #29332e; border-radius: 0; background: transparent; }
html[data-theme] .icon-btn:hover { border-color: #ff3b30; color: #ff3b30; }

/* 首页：监控画面框 */
html[data-theme] .main { padding: 0 20px 118px; }
html[data-theme] .ledger-mast {
  position: relative; margin-top: 16px; padding: 22px; border: 1px solid #334039; border-radius: 0;
  background:
    linear-gradient(180deg, rgba(120, 150, 135, 0.08), transparent 46%),
    #0b100e;
  box-shadow: inset 0 0 60px -30px #000;
}
html[data-theme] .ledger-mast::before {
  content: "● REC    CAM-01";
  position: absolute; top: 10px; right: 12px;
  font-family: var(--mono); font-size: 11px; letter-spacing: 0.16em; color: #ff3b30;
  animation: rec-blink 1.6s steps(2) infinite;
}
@keyframes rec-blink { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0.25; } }
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--serif); font-size: clamp(30px, 4vw, 54px); line-height: 1.06;
  letter-spacing: 0.02em; text-transform: uppercase; color: #e4ebe7;
  text-shadow: 0 0 24px rgba(213, 221, 216, 0.18);
}
html[data-theme] .ledger-mast h1 em { color: #ff3b30; }
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #8d9a93; font-family: var(--mono); font-size: 11px; letter-spacing: 0.04em; }

html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 1px solid #29332e; border-radius: 0; background: #0e1311; box-shadow: none;
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
html[data-theme] .card { padding: 14px 16px; }
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover { border-color: #ff3b30; transform: none; }
html[data-theme] .btn {
  border: 1px solid #334039; border-radius: 0; background: transparent; color: #c6cfc9;
  font-family: var(--mono); font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; padding: 6px 10px;
}
html[data-theme] .btn.primary { background: #ff3b30; color: #0b0b0c; border-color: #ff3b30; }
html[data-theme] .btn:hover { border-color: #ff3b30; color: #ff3b30; }
html[data-theme] .btn.primary:hover { color: #0b0b0c; background: #ff564d; }

/* 统计 */
html[data-theme] #page-stats .page-head {
  margin: 14px 0; padding: 18px 20px; border: 1px solid #334039; border-radius: 0; background: #0b100e;
}
html[data-theme] #page-stats .page-head h1 {
  font-family: var(--serif); font-size: clamp(24px, 3vw, 40px); letter-spacing: 0.02em; text-transform: uppercase; color: #e4ebe7;
  background: none; -webkit-text-fill-color: #e4ebe7;
}
html[data-theme] #page-stats .eyebrow { color: #ff3b30; font-family: var(--mono); font-size: 11px; letter-spacing: 0.26em; }
html[data-theme] #page-stats .stat {
  border: 1px solid #29332e; border-radius: 0; background: #0e1311; padding: 14px 16px; box-shadow: none;
}
html[data-theme] #page-stats .stat:before { content: ""; background: #ff3b30; width: 2px; opacity: 1; }
html[data-theme] #page-stats .stat label { color: #8d9a93; font-family: var(--mono); font-size: 11px; letter-spacing: 0.16em; }
html[data-theme] #page-stats .stat strong {
  margin: 8px 0 2px; font-family: var(--serif); font-size: 30px; letter-spacing: 0.01em; color: #e4ebe7;
  background: none; -webkit-text-fill-color: #e4ebe7;
}
html[data-theme] #page-stats .stat em { color: #7f8d86; font-size: 11px; }
html[data-theme] #page-stats .card { padding: 14px 16px; }
html[data-theme] #page-stats .section-title { font-family: var(--mono); font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; border-bottom: 1px dashed #29332e; padding-bottom: 8px; }
html[data-theme] #page-stats .stat-bar { padding: 7px 0; border-radius: 0; background: transparent; border-bottom: 1px dotted #29332e; }
html[data-theme] #page-stats .stat-bar:hover { background: #131a16; }
html[data-theme] #page-stats .stat-bar-head span { font-family: var(--mono); font-size: 11px; color: #c6cfc9; }
html[data-theme] #page-stats .stat-bar-head b { font-family: var(--mono); font-size: 11px; color: #8d9a93; }
html[data-theme] #page-stats .stat-track { height: 4px; border-radius: 0; background: #1f2723; box-shadow: none; }
html[data-theme] #page-stats .stat-track i { border-radius: 0; background: #ff3b30; box-shadow: 0 0 8px rgba(255, 59, 48, 0.6); }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 22px; padding: 18px 20px; border: 1px solid #334039; border-radius: 0; background: #0b100e;
}
html[data-theme] #page-stats .year-title { font-family: var(--serif); font-size: 34px; text-transform: uppercase; letter-spacing: 0.02em; color: #e4ebe7; background: none; -webkit-text-fill-color: #e4ebe7; }
html[data-theme] #page-stats #echoYear { border: 1px solid #334039; border-radius: 0; background: #0e1311; color: #c6cfc9; font-family: var(--mono); font-size: 11px; }
html[data-theme] #page-stats #echoBody { padding: 16px; }

/* 设置 */
html[data-theme] .ct-box { border: 1px solid #29332e; border-radius: 0; background: #0e1311; }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid #29332e; border-radius: 0; background: #080c0a; color: #a9b7ae;
}

/* 播放舱 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 12px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 10px 18px 12px; border: 1px solid #334039; border-radius: 0;
    background: #0a0e0c; box-shadow: 0 0 0 1px #1a2420, 0 0 34px -16px rgba(255, 59, 48, 0.24);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn { border-radius: 0; background: #ff3b30; color: #ffffff; box-shadow: 0 0 16px rgba(255, 59, 48, 0.5); }
html[data-theme] .mini-player { border: 1px solid #334039; border-radius: 0; background: #0a0e0c; }

html[data-theme] .cue.active .word { color: #ffffff; background: rgba(255, 59, 48, 0.22); border-radius: 0; }
html[data-theme] ::-webkit-scrollbar-thumb { background: #3b4a43; border-radius: 0; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: radial-gradient(120% 100% at 50% 50%, #141a17 0%, #0a0d0c 62%, #050706 100%); color: #d5ddd8; }
html[data-theme] .wp-bg { filter: blur(30px) grayscale(.9) contrast(1.35) brightness(.5) saturate(.6); opacity: .9; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(5,7,6,.95) 0%, rgba(10,13,12,.86) 50%, rgba(5,7,6,.8) 78%, rgba(5,7,6,.96) 100%), radial-gradient(120% 100% at 50% 50%, transparent 40%, rgba(0,0,0,.8) 100%); }
html[data-theme] .wp-kicker { color: #ff3b30; font-weight:700;letter-spacing:.28em;text-transform:uppercase; }
html[data-theme] .wp-title { color: #c9d2cc; font-weight:600;letter-spacing:.06em;text-transform:uppercase; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(141,154,147,.82); }
html[data-theme] .wp-cue.active::before { background: #ff3b30; box-shadow: 0 0 18px rgba(255,59,48,.6); width:3px;border-radius:0; }
html[data-theme] .wp-cue.active .wp-en { color: #e6ece8; text-shadow: none; font-weight:600;letter-spacing:-.01em; }
html[data-theme] .wp-word.past { color: #e6ece8; }
html[data-theme] .wp-word.active { color: #ffffff; background-image: linear-gradient(180deg, transparent 62%, rgba(255,59,48,.4) 62%, rgba(255,59,48,.18) 94%, transparent 94%); text-shadow: none; border-radius:0; }
html[data-theme] .wp-zh { color: rgba(141,154,147,.8); font-weight:400; }
html[data-theme] .wp-label { color: rgba(141,154,147,.5); }
html[data-theme] .wpbtn { background: rgba(10,13,12,.8); border-color: #29332e; color: #d5ddd8; border-radius:0;letter-spacing:.18em;text-transform:uppercase;box-shadow:0 0 0 1px rgba(255,59,48,.18); }
html[data-theme] .wpbtn:hover { background: rgba(255,59,48,.18); border-color: #ff3b30; color: #ffffff; }
html[data-theme] .wp-shade::after { background: repeating-linear-gradient(0deg, rgba(213,221,216,.09) 0 1px, transparent 1px 3px); }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .dstile { background: #0d1210; border: 1px solid #26302b; border-radius: 2px; color: #d5ddd8; font-family: var(--mono); }
html[data-theme] .dstile svg { stroke: #7f8f86; }
html[data-theme] .dstile:hover { border-color: var(--accent); color: #fff; background: #121816; }
html[data-theme] .dstile:hover svg { stroke: var(--accent); }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { border-color: var(--accent); background: rgba(255,59,48,.1); color: #ffd7d3; }
html[data-theme] .dshead h4 { color: var(--accent); }
html[data-theme] .dspill { border-radius: 2px; border-color: #26302b; color: #c3cfc8; font-family: var(--mono); }
html[data-theme] .dspill.on { border-color: var(--accent); color: var(--accent); background: rgba(255,59,48,.1); }
html[data-theme] .dsrange::-webkit-slider-thumb { -webkit-appearance: none; width: 10px; height: 16px; border-radius: 1px; background: var(--accent); }

/* ---------- 可访问性收尾（2026-11-21，与液态玻璃同一套标准） ---------- */
/* 列表里的时长/时间点用等宽数字，12:04 与 1:02:04 的冒号能竖着对齐 */
html[data-theme] :where(.ep-dur, .dur, .time, .clock, .dst-time, .wp-time) {
  font-variant-numeric: tabular-nums;
}
/* 大标题与副标题防孤字 */
html[data-theme] :where(.page-head h1, .ledger-mast h1, .year-title, .page-head .subtitle) {
  text-wrap: balance;
}
/* 按下态：这套主题的按钮只有 hover，没有点击反馈 */
html[data-theme] :where(.btn, .icon-btn, .rail-toggle, .round-play, .sidebar-add, .nav button):active {
  transform: translateY(1px);
  filter: brightness(0.96);
}
/* 选中文字跟随主题强调色，别用系统蓝 */
html[data-theme] ::selection {
  background: color-mix(in srgb, var(--accent) 26%, transparent);
}
/* 基础样式已有全局 2px 焦点描边，这里只把圈收进来一点，避免被圆角切掉 */
html[data-theme] :where(button, [role="button"], [role="tab"], a[href]):focus-visible {
  outline-offset: 1px;
}
/* 尊重系统「减少动态效果」：漂移/闪烁/位移都是纯装饰，状态变化靠颜色与描边表达 */
@media (prefers-reduced-motion: reduce) {
  html[data-theme] *, html[data-theme] *::before, html[data-theme] *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  html[data-theme] :where(.nav button, .pod-card, .continue, .stat, .dstile,
    .theme-card, .custom-card, .ep-row, .swatch):hover {
    transform: none !important;
  }
}

/* 首页卡片内衬：底座把 .ledger-home .pod-card 的内距清零、封面出血；本主题给卡片描边后
   必须自己把字与按钮推回内衬里，否则贴边框；并让四张卡按钮同基线 */
html[data-theme] .ledger-home .pod-card { padding: 0 0 14px; overflow: hidden; }
html[data-theme] .ledger-home .pod-card .pod-card-main { flex: 1 1 auto; }
html[data-theme] .ledger-home .pod-card .pod-card-main > :not(.pod-art) { margin-left: 14px; margin-right: 14px; }
html[data-theme] .ledger-home .pod-card .pod-actions { margin: 12px 14px 0; }
